    for operation in operations:
        balance += operation
        if balance < 0:
            return True
    return False

def mean_absolute_deviation(numbers: List[float]) -> float:
    try:
        x_mean = sum(numbers) / len(numbers)
        deviations = [abs(x - x_mean) for x in numbers]
        return sum(deviations) / len(numbers)
    except ZeroDivisionError:
        raise ValueError("Cannot calculate mean absolute deviation for empty list")
    except TypeError:
        raise TypeError("Invalid input type, expected a list of float values")

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Initialize the dynamic programming table
    dp = [[0] * N for _ in range(N)]

    # Populate the table with the values from the grid
    for (x, y, value) in grid_values:
        if x < N and y < N:
            dp[x][y] = value

    # Compute the maximum values on each row and store them in a separate array
    row_values = [0] * N
    for i in range(N):
        for j in range(N):
            row_values[i] = max(row_values[i], dp[i][j])

    # Compute the maximum values on each column and store them in a separate array
    col_values = [0] * N
    for j in range(N):
        for i in range(N):
            col_values[j] = max(col_values[j], dp[i][j])

    # Compute the maximum value by combining the values on each row and column
    max_value = 0
    for i in range(N):
        for j in range(N):
            max_value = max(max_value, row_values[i] + col_values[j])

    return max_value

