def sum_of_factorials_optimized(n: int) -> int:
    if n < 1 or n > 50:
        raise ValueError("n must be in the range of 1 to 50, inclusive.")
    result = 0
    for i in range(1, n+1):
        result += factorial(i)
    return result

def factorial(n):
    if n == 0:
        return 1
    else:
        return n * factorial(n-1)

