def optimize_seating(M, N, K, L, D, chatting_pairs):
    # Initialize a 2D matrix to represent the classroom seating arrangement
    classroom = [[0 for _ in range(N)] for _ in range(M)]

    # Place students in the classroom based on their positions
    for pair in chatting_pairs:
        classroom[pair[0] - 1][pair[1] - 1] += 1
        classroom[pair[2] - 1][pair[3] - 1] += 1

    # Initialize a list to store the number of chatting pairs that can be separated by each aisle position
    aisle_seperations = [0] * (M * N)

    # Iterate through each possible aisle position and count the number of chatting pairs that can be separated
    for i in range(M):
        for j in range(N):
            if classroom[i][j] == 0:
                continue
            for k in range(M):
                for l in range(N):
                    if classroom[k][l] == 0:
                        continue
                    aisle_seperations[i * N + j] += 1

    # Select the most effective aisle positions based on the number of chatting pairs they can separate
    aisle_positions = sorted(range(M * N), key=lambda x: aisle_seperations[x], reverse=True)[:K * L]

    # Convert the selected aisle positions into row and column indices
    row_indices = [int(i / N) + 1 for i in aisle_positions]
    col_indices = [i % N + 1 for i in aisle_positions]

    return " ".join(str(i) for i in row_indices), " ".join(str(i) for i in col_indices)

def count_passing_ways(n: int, m: int) -> int:
    if n < 1 or m < 1:
        raise ValueError("n and m must be positive integers")
    if n == 1:
        return 1
    if m == 1:
        return n
    if m > n:
        raise ValueError("m must be less than or equal to n")
    cache = {1: 1, 2: 2}
    for i in range(3, n+1):
        cache[i] = (cache[i-1] + cache[i-2]) % 1000000007
    return cache[m]

def max_energy(beads):
    # Initialize dynamic programming memoization table
    memo = [[0] * len(beads) for _ in range(len(beads))]

    # Initialize base case
    for i in range(len(beads)):
        memo[i][i] = beads[i]

    # Iterate through beads and compute maximum energy release for each possible pair
    for i in range(len(beads) - 1):
        for j in range(i + 1, len(beads)):
            memo[i][j] = max(memo[i + 1][j], beads[i] * memo[i + 1][j - 1])

    # Return maximum energy release
    return max(memo[0][len(beads) - 1], memo[1][0])

def polynomial_to_string(n, coeffs)
    result = ''

    for i, coeff in enumerate(coeffs):
        if coeff == 0:
            continue

        deg = n - i
        var = 'x^' + str(deg) if deg > 1 else 'x' * deg

        if result != '':
            result += '+'

        if coeff == 1 and deg == 1:
            result += var
        else:
            sign = '-' if coeff < 0 else '+'

            result += sign + absl(coeff) + var

    return result

def select_volunteers(n: int, m: int, applicants: List[Tuple[int, int]]) -> Tuple[int, List[Tuple[int, int]]]:
    # Sort applicants based on test score in descending order
    applicants.sort(key=lambda x: x[1], reverse=True)

    # Calculate the interview score cutoff as 150% of the planned number of recruits
    cutoff = round(1.5 * m)

    # Initialize the list of qualified applicants with the top (cutoff) scores
    qualified_applicants = []
    for i in range(cutoff):
        qualified_applicants.append(applicants[i])

    # Add the remaining applicants with scores equal to or higher than the cutoff
    for i in range(cutoff, n):
        if applicants[i][1] >= cutoff:
            qualified_applicants.append(applicants[i])

    # Return the interview score cutoff and the list of qualified applicants
    return (cutoff, qualified_applicants)

def largest_prime_factor(n: int) -> int:
    if n < 2:
        raise ValueError("n must be a positive integer")

    i = 2
    while i * i <= n:
        if n % i == 0:
            return n // i
        i += 1

    return n

def count_partitions(n, k, x):
    if n < k * x or k < 1 or x < 1:
        return 0
    if k == 1:
        return 1
    if n == k * x:
        return 1
    if x == 1:
        return count_partitions(n, k - 1, x)
    return count_partitions(n - x, k, x) + count_partitions(n, k - 1, x)

def count_sequences(n: int, last: int, memo: dict) -> int:
    if n == last:
        return 1
    if n not in memo:
        memo[n] = 0
        for i in range(1, int(last / 2) + 1):
            memo[n] += count_sequences(n + i, i, memo)
    return memo[n]

def count_coprime_pairs(x0: int, y0: int) -> int:
    count = 0
    for a in range(1, y0 // x0 + 1):
        b = y0 // x0 // a
        if is_coprime(a, b):
            if a == b:
                count += 1
            else:
                count += 2
    return count

def is_coprime(a: int, b: int):
    return a == 1 or b == 1 or gcd(a, b) == 1

def gcd(a: int, b: int):
    if b == 0:
        return a
    else:
        return gcd(b, a % b)

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    class BreadthFirstSearch:
        def __init__(self, A, B, rules):
            self.A = A
            self.B = B
            self.rules = rules
            self.queue = [(A, "")].
            self.steps = 0

        def next_step(self):
            step = self.queue.pop(0)
            for rule in self.rules:
                if rule[0] in step[0]:
                    step[0] = step[0].replace(rule[0], rule[1])
                    self.queue.append((step[0], step[1] + 1))
            return step

        def is_solution(self):
            return self.steps < 10 and self.queue[0][0] == self.B

    bfs = BreadthFirstSearch(A, B, rules)
    while bfs.is_solution():
        bfs.next_step()
    return bfs.steps if bfs.is_solution() else "NO ANSWER!"

