def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num == 2 or num == 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_numbers(n, rules):
    # Initialize a set to store all generated numbers
    generated_numbers = set()

    # Add the original number to the set
    generated_numbers.add(n)

    # Iterate through the rules and apply transformations
    for x, y in rules:
        # Create a new set to store the transformed numbers
        transformed_numbers = set()

        # Iterate through the generated numbers and apply the transformation rule
        for num in generated_numbers:
            # If the digit being transformed is the one specified in the rule, transform it
            if str(num)[-1] == x:
                transformed_numbers.add(num[:-1] + y)
            else:
                transformed_numbers.add(num)

        # Add the transformed numbers to the set
        generated_numbers |= transformed_numbers

    # Return the count of unique numbers
    return len(generated_numbers)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Checks if a given scenario is consistent with the statements made by all participants.

    :param scenario: The name of the participant being tested as the potential criminal.
    :param liar_count: A set of names of participants who are assumed to be liars.
    :param statements: A dictionary mapping participant names to lists of their respective statements.
    :param days_of_week: A set of strings representing the days of the week.
    :return: True if the scenario is consistent, False otherwise.
    """
    # Check if all participants have made statements
    if not all(name in statements for name in liar_count):
        raise ValueError("Not all participants have made statements.")

    # Check if the given scenario is in the statement
    if scenario not in [name for name, statement in statements.items() for statement in statement]:
        return False

    # Check if all statements are consistent with the scenario
    for name, statement in statements.items():
        if name == scenario:
            continue
        elif name in liar_count:
            if scenario not in statement:
                return False
        elif scenario in statement:
            return False

    return True

