def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Initialize a dictionary to store the maximum volume that can be occupied
    # by any subset of the given items for each i values from 0 to n
    dp = {0: 0}

    # Loop through each item
    for i in range(n):
        # Loop through the previous maximum volume that can be occupied
        for j in range(V):
            # If the current item's volume is less than or equal to the remaining space
            if volumes[i] <= j:
                # Update the maximum volume that can be occupied
                dp[i+1] = max(dp[i], dp[i-1] + volumes[i])
            else:
                # If the current item's volume is greater than the remaining space
                # Update the maximum volume that can be occupied
                dp[i+1] = dp[i]

    # Return the difference between the box's total capacity and the maximum occupied volume
    return V - dp[n]

def calculate_arrangements(n, m, a):
    def _helper(n, m, a, cur_type, cur_pots):
        if cur_type == len(a):
            return 1
        if cur_pots == 0:
            return 0
        if cur_type == n:
            return 0
        total = 0
        for i in range(1, min(a[cur_type], cur_pots) + 1):
            total += _helper(n, m - i, a, cur_type + 1, cur_pots - i)
        return total
    return _helper(n, m, a, 0, m) % (10**6 + 7)

def vigenere_decrypt(key, ciphertext):
    keychars = set(key.lower())
    cipherchars = [c.lower() for c in ciphertext]
    decrypted = []
    for i in range(len(cipherchars)):
        c = cipherchars[i]
        if c not in keychars:
            decrypted.append(c)
            continue
        k = key[i % len(key)]
        if k == c:
            decrypted.append(c)
        else:
            decrypted.append(chr(((ord(c) - ord(k)) % 26) + ord('a')))
    return ''.join(decrypted)

