def min_groups(w, n, prices):
    groups = []
    group_total = 0
    for i, price in enumerate(prices):
        if group_total + price <= w:
            group_total += price
            if i + 1 == n:
                groups.append(group_total)
                break
        else:
            groups.append(group_total)
            group_total = price
    return len(groups)

def hanoi_double_iterative(n: int) -> int:
    if n == 1:
        return 2
    elif n <= 0:
        raise ValueError("n must be a positive integer")

    # Define the recursive relation
    def min_moves(n):
        if n == 1:
            return 2
        else:
            return 2 * min_moves(n - 1) + 2

    # Compute the total number of moves iteratively
    total_moves = 0
    for i in range(n):
        total_moves += min_moves(i)

    return total_moves

